mapper.select:
SELECT review_id, essay_id, task_id, rule_version, reviewer_type, reviewer_id, model_version, start_time, end_time, total_score, status, error_msg, retry_count, create_time, is_deleted FROM review_record WHERE is_deleted = 0
AND status = #{status}
AND reviewer_type = #{reviewerType}
ORDER BY create_time DESC

mapper.update:
UPDATE score_dimension
SET status = #{status}
WHERE dimension_id = #{id} AND is_deleted = 0
